def nest(flat):
    out={}
    for k,v in flat.items():
        parts=k.split('.'); d=out
        for p in parts[:-1]:
            d=d.setdefault(p,{})
            assert isinstance(d,dict),k
        assert parts[-1] not in d or not isinstance(d[parts[-1]],dict),k
        d[parts[-1]]=v
    return out
